    #[test]
    fn standard_host_preserves_instance_receivers_and_neutral_unknowns() {
        let mut host = StdHost::new();
        let length = MethodRef {
            owner: "java/lang/String".into(),
            name: "length".into(),
            descriptor: "()I".into(),
        };
        assert_eq!(
            host.invoke_instance(&length, &Value::Ref(Some("hé".into())), &[])
                .unwrap(),
            Value::Int(2)
        );
        let unknown = MethodRef {
            owner: "demo/Unknown".into(),
            name: "run".into(),
            descriptor: "()Ljava/lang/Object;".into(),
        };
        assert_eq!(host.invoke(&unknown, &[]).unwrap(), Value::Ref(None));
        assert_eq!(host.calls(), &[length, unknown]);
        assert_eq!(
            host.invocations()[0].receiver,
            Some(Value::Ref(Some("hé".into())))
        );
        assert_eq!(host.invocations()[1].args, Vec::new());
    }

    #[test]
    fn standard_host_can_fail_closed_and_report_unknown_calls() {
        let unknown = MethodRef {
            owner: "demo/Unknown".into(),
            name: "run".into(),
            descriptor: "()I".into(),
        };
        let mut host = StdHost::new().with_strict_unknown_host_calls();
        let error = host.invoke(&unknown, &[]).unwrap_err();
        assert!(matches!(error, NativeError::UnknownHostCall(_)));
        assert_eq!(
            host.unknown_host_calls(),
            vec![("demo/Unknown#run()I".into(), 1)]
        );
        assert_eq!(host.unknown_host_call_count(), 1);
        host.set_strict_unknown_host_calls(false);
        assert_eq!(host.invoke(&unknown, &[]).unwrap(), Value::Int(0));
        assert_eq!(host.unknown_host_call_count(), 2);
    }

    #[test]
    fn standard_host_retains_persistent_class_state_with_bounds() {
        let mut host = StdHost::new();
        let fields = BTreeMap::from([("demo/Entry#COUNTI".to_owned(), Value::Int(7))]);
        let initialized = std::collections::BTreeSet::from(["demo/Entry".to_owned()]);
        host.store_persistent_class_state(fields.clone(), initialized.clone())
            .unwrap();
        assert_eq!(host.persistent_class_state(), (fields, initialized));
        let too_many = (0..=MAX_PERSISTENT_CLASS_FIELDS)
            .map(|index| {
                (
                    format!("demo/Entry#field{index}I"),
                    Value::Int(index as i32),
                )
            })
            .collect();
        assert!(
            host.store_persistent_class_state(too_many, std::collections::BTreeSet::new())
                .is_err()
        );
    }

