    /// The `javac` a fixture should use, or `None` when no JDK is installed.
    fn javac() -> Option<PathBuf> {
        let from_home = std::env::var_os("JAVA_HOME")
            .map(|home| PathBuf::from(home).join("bin/javac"))
            .filter(|path| path.exists());
        let javac = from_home.unwrap_or_else(|| PathBuf::from("javac"));
        Command::new(&javac)
            .arg("-version")
            .output()
            .ok()
            .filter(|output| output.status.success())
            .map(|_| javac)
    }

    #[test]
    fn field_selectors_accept_the_bounded_owner_forms() {
        let full = parse_field_selector("Ldemo/Target;count:I").expect("descriptor form");
        assert_eq!(full.owner.as_deref(), Some("demo/Target"));
        assert_eq!(full.name, "count");
        assert_eq!(full.descriptor.as_deref(), Some("I"));

        let binary = parse_field_selector("demo.Target#count:I").expect("binary owner");
        assert_eq!(binary.owner.as_deref(), Some("demo/Target"));
        let slashed = parse_field_selector("demo/Target#count").expect("slashed owner");
        assert_eq!(slashed.owner.as_deref(), Some("demo/Target"));
        assert_eq!(slashed.descriptor, None);
        let ownerless = parse_field_selector("#count").expect("ownerless");
        assert_eq!(ownerless.owner, None);
        assert_eq!(ownerless.name, "count");
        let name_and_descriptor = parse_field_selector("count:J").expect("name and descriptor");
        assert_eq!(name_and_descriptor.owner, None);
        assert_eq!(name_and_descriptor.descriptor.as_deref(), Some("J"));

        assert!(parse_field_selector("Ldemo/Target;count:NotADescriptor").is_none());
        assert!(parse_field_selector("has spaces").is_none());
    }

    #[test]
    fn anchor_sites_resolve_new_and_jump_shapes() {
        let plan = |at: &str, site: Option<&str>, opcode: Option<u8>| MixinAnchorPlan {
            target: MethodRef {
                owner: "demo/Target".into(),
                name: "run".into(),
                descriptor: "()V".into(),
            },
            callback: MethodRef {
                owner: "demo/Mixin".into(),
                name: "hook".into(),
                descriptor: "()V".into(),
            },
            at: at.into(),
            site: site.map(str::to_owned),
            opcode,
            cancellable: false,
            ordinal: None,
            slice_from: None,
            slice_to: None,
            shift: None,
            redirect: false,
        };

        assert_eq!(
            resolve_anchor_site(&plan("NEW", Some("Ldemo/Made;"), None)).unwrap(),
            ResolvedAnchor::New("demo/Made".into())
        );
        assert_eq!(
            resolve_anchor_site(&plan("JUMP", None, None)).unwrap(),
            ResolvedAnchor::Jump {
                opcode: None,
                offset: None
            }
        );
        assert_eq!(
            resolve_anchor_site(&plan("JUMP", Some("demo/Target;run()V:42"), Some(154))).unwrap(),
            ResolvedAnchor::Jump {
                opcode: Some(154),
                offset: Some(42)
            }
        );
        assert!(resolve_anchor_site(&plan("JUMP", Some("not-an-offset"), None)).is_err());
        assert!(resolve_anchor_site(&plan("JUMP", None, Some(0x2a))).is_err());

        // `@Slice` is a modifier, not part of the site: the load-time weaver
        // applies it, and the interpreter refuses it where it executes.
        let mut sliced = plan("FIELD", Some("#count:I"), None);
        sliced.slice_from = Some("HEAD".into());
        sliced.slice_to = Some("RETURN".into());
        assert_eq!(
            resolve_anchor_site(&sliced).unwrap(),
            ResolvedAnchor::Field(parse_field_selector("#count:I").unwrap())
        );
    }

    #[test]
    fn anchor_modifiers_resolve_slice_and_shift_distances() {
        let selector = |anchor: &str, shift: Option<&str>, by: Option<i32>| AtSelector {
            anchor: anchor.into(),
            target: Some("#count:I".into()),
            opcode: None,
            ordinal: None,
            shift: shift.map(str::to_owned),
            by,
            slice_from: None,
            slice_to: None,
        };
        let bounded = |shift| Some(ShiftBy { by: shift });

        assert_eq!(
            resolve_anchor_modifiers(&selector("FIELD", None, None), false),
            Ok(None)
        );
        assert_eq!(
            resolve_anchor_modifiers(&selector("FIELD", Some("NONE"), None), false),
            Ok(None)
        );
        assert_eq!(
            resolve_anchor_modifiers(&selector("FIELD", Some("BEFORE"), None), false),
            Ok(bounded(-1))
        );
        assert_eq!(
            resolve_anchor_modifiers(&selector("FIELD", Some("AFTER"), None), false),
            Ok(bounded(2))
        );
        assert_eq!(
            resolve_anchor_modifiers(&selector("FIELD", Some("AFTER"), Some(2)), false),
            Ok(bounded(3))
        );
        assert_eq!(
            resolve_anchor_modifiers(&selector("JUMP", Some("BY"), Some(-3)), false),
            Ok(bounded(-3))
        );

        // A shift outside the bounded distance, an unknown direction and a
        // `by` without a shift are reasons, not silent no-ops.
        assert!(
            resolve_anchor_modifiers(&selector("FIELD", Some("AFTER"), Some(8)), false).is_err()
        );
        assert!(resolve_anchor_modifiers(&selector("FIELD", Some("BY"), Some(99)), false).is_err());
        assert!(
            resolve_anchor_modifiers(&selector("FIELD", Some("SOMEWHERE"), None), false).is_err()
        );
        assert!(resolve_anchor_modifiers(&selector("FIELD", None, Some(2)), false).is_err());
        // A redirect's replacement bytes have to stay on the instruction.
        assert!(resolve_anchor_modifiers(&selector("FIELD", Some("BEFORE"), None), true).is_err());

        // Anchors accept the same bounded `@Slice` vocabulary as injections.
        let mut sliced = selector("FIELD", None, None);
        sliced.slice_from = Some("HEAD".into());
        sliced.slice_to = Some("RETURN".into());
        assert_eq!(resolve_anchor_modifiers(&sliced, false), Ok(None));
        sliced.slice_to = Some("INVOKE:Ldemo/Probe;mark(Ljava/lang/String;I)V".into());
        assert_eq!(resolve_anchor_modifiers(&sliced, false), Ok(None));
        sliced.slice_to = Some("STORE".into());
        assert!(resolve_anchor_modifiers(&sliced, false).is_err());
        sliced.slice_to = None;
        assert!(resolve_anchor_modifiers(&sliced, false).is_err());
    }

    #[test]
    fn anchor_plan_shift_reaches_the_anchor_request() {
        let plan = MixinAnchorPlan {
            target: MethodRef {
                owner: "demo/Target".into(),
                name: "run".into(),
                descriptor: "()V".into(),
            },
            callback: MethodRef {
                owner: "demo/Mixin".into(),
                name: "hook".into(),
                descriptor: "()V".into(),
            },
            at: "FIELD".into(),
            site: Some("#count:I".into()),
            opcode: None,
            cancellable: false,
            ordinal: None,
            slice_from: Some("HEAD".into()),
            slice_to: Some("RETURN".into()),
            shift: Some(ShiftBy { by: 2 }),
            redirect: false,
        };
        let request = weaver::AnchorRequest::from_plan(&plan).expect("a bounded plan");
        assert_eq!(request.shift, Some(ShiftBy { by: 2 }));
        assert_eq!(
            request.slice,
            Some(SliceBounds {
                from: SiteSelector::Head,
                to: SiteSelector::Return,
            })
        );
    }

    #[test]
    fn modify_arg_slices_resolve_from_the_inline_or_annotation_selector() {
        let selector = |slice_from: Option<&str>, slice_to: Option<&str>| AtSelector {
            anchor: "INVOKE".into(),
            target: Some("Ldemo/Probe;mark(Ljava/lang/String;I)V".into()),
            opcode: None,
            ordinal: None,
            shift: None,
            by: None,
            slice_from: slice_from.map(str::to_owned),
            slice_to: slice_to.map(str::to_owned),
        };

        assert_eq!(
            resolve_modify_arg_slice(&selector(None, None), &[]),
            Ok(None)
        );
        assert_eq!(
            resolve_modify_arg_slice(&selector(Some("HEAD"), Some("RETURN")), &[]),
            Ok(Some(SliceBounds {
                from: SiteSelector::Head,
                to: SiteSelector::Return,
            }))
        );
        // An annotation-level `@ModifyArg.slice` applies when the `@At` has no
        // nested one; more than one is ambiguous.
        assert_eq!(
            resolve_modify_arg_slice(
                &selector(None, None),
                &[(Some("HEAD".into()), Some("TAIL".into()))]
            ),
            Ok(Some(SliceBounds {
                from: SiteSelector::Head,
                to: SiteSelector::Tail,
            }))
        );
        assert!(
            resolve_modify_arg_slice(
                &selector(None, None),
                &[
                    (Some("HEAD".into()), Some("TAIL".into())),
                    (Some("HEAD".into()), Some("RETURN".into())),
                ]
            )
            .is_err()
        );
        assert!(resolve_modify_arg_slice(&selector(Some("HEAD"), None), &[]).is_err());
    }

    #[test]
    fn executes_bounded_mixin_injection_at_head_before_target() {
        let target = ClassFile {
            name: "demo/Target".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "tick".into(),
                descriptor: "()I".into(),
                access: 9,
                code: Some(vec![0x08, 0xac]), // iconst_5; ireturn
                max_locals: 0,
                max_stack: 0,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let callback = ClassFile {
            name: "demo/Mixin".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "onTick".into(),
                descriptor: "(Lorg/spongepowered/asm/mixin/injection/callback/CallbackInfo;)V"
                    .into(),
                access: 9,
                code: Some(vec![0xb1]),
                max_locals: 1,
                max_stack: 0,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let jar = NativeJar::from_classes([target, callback]);
        let plan = MixinInjectionPlan::inject_at_head(
            MethodRef {
                owner: "demo/Target".into(),
                name: "tick".into(),
                descriptor: "()I".into(),
            },
            MethodRef {
                owner: "demo/Mixin".into(),
                name: "onTick".into(),
                descriptor: "(Lorg/spongepowered/asm/mixin/injection/callback/CallbackInfo;)V"
                    .into(),
            },
        );
        let report = jar
            .execute_mixin_at_head(&plan, None, &[], &mut NullHost)
            .unwrap();
        assert_eq!(report.callback_result, Value::Void);
        assert_eq!(report.target_result, Value::Int(5));
    }

