    /// A target whose whole body is `return demo/Probe.value();`, so a
    /// cancelled invoke's replacement value is the woven method's result.
    fn invoke_target_class() -> ClassFile {
        ClassFile {
            name: "demo/Target".into(),
            super_name: "java/lang/Object".into(),
            pool: probe_pool("value", "()I"),
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![test_method(
                "value",
                "()I",
                vec![0xb8, 0x00, 0x06, 0xac], // invokestatic demo/Probe.value; ireturn
                Vec::new(),
            )],
            annotations: Vec::new(),
            raw: Vec::new(),
        }
    }

    /// Constant pool naming one `demo/Probe#name` call.
    fn probe_pool(name: &str, descriptor: &str) -> Vec<Cp> {
        vec![
            Cp::Empty,
            Cp::Utf8("demo/Probe".into()),
            Cp::Class(1),
            Cp::Utf8(name.into()),
            Cp::Utf8(descriptor.into()),
            Cp::NameType {
                name: 3,
                descriptor: 4,
            },
            Cp::MethodRef { class: 2, nt: 5 },
        ]
    }

    /// A static callback that calls `CallbackInfo.cancel()`.
    fn cancel_invoke_mixin() -> ClassFile {
        ClassFile {
            name: "demo/InvokeMixin".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![
                Cp::Empty,
                Cp::Utf8(CALLBACK_INFO_CLASS.into()),
                Cp::Class(1),
                Cp::Utf8("cancel".into()),
                Cp::Utf8("()V".into()),
                Cp::NameType {
                    name: 3,
                    descriptor: 4,
                },
                Cp::MethodRef { class: 2, nt: 5 },
            ],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![test_method(
                "onValue",
                "(Lorg/spongepowered/asm/mixin/injection/callback/CallbackInfo;)V",
                // aload_0; invokevirtual CallbackInfo.cancel; return
                vec![0x2a, 0xb6, 0x00, 0x06, 0xb1],
                Vec::new(),
            )],
            annotations: Vec::new(),
            raw: Vec::new(),
        }
    }

    fn invoke_plan(invoke_target: MethodRef, cancellable: bool) -> MixinInjectionPlan {
        let mut plan = MixinInjectionPlan::inject_at_invoke(
            MethodRef {
                owner: "demo/Target".into(),
                name: "value".into(),
                descriptor: "()I".into(),
            },
            MethodRef {
                owner: "demo/InvokeMixin".into(),
                name: "onValue".into(),
                descriptor: format!("({CALLBACK_INFO_DESC})V"),
            },
            invoke_target,
        );
        plan.cancellable = cancellable;
        plan
    }

    /// Answers the stubbed call with 42, so a cancelled invoke that answers the
    /// descriptor default (0) is distinguishable from the call itself.
    struct ValueHost {
        calls: usize,
    }

    impl Host for ValueHost {
        fn invoke(&mut self, r: &MethodRef, _: &[Value]) -> Result<Value, NativeError> {
            self.calls += 1;
            Ok(if r.owner == "demo/Probe" && r.name == "value" {
                Value::Int(42)
            } else {
                Value::default_for(return_desc(&r.descriptor))
            })
        }
    }

    #[test]
    fn invoke_selectors_parse_all_supported_forms() {
        let block_state = "Lnet/minecraft/world/level/block/state/BlockState;";
        // `Lowner;name(descriptor)`.
        let site = parse_invoke_selector(&format!(
            "Lnet/minecraft/world/level/Level;getBlockState(Lnet/minecraft/core/BlockPos;){block_state}"
        ))
        .unwrap();
        assert_eq!(
            site,
            MethodRef {
                owner: "net/minecraft/world/level/Level".into(),
                name: "getBlockState".into(),
                descriptor: format!("(Lnet/minecraft/core/BlockPos;){block_state}"),
            }
        );

        // Slashed owner with `.` between owner and name.
        let site = parse_invoke_selector(&format!(
            "net/minecraft/world/level/Level.getBlockState(Lnet/minecraft/core/BlockPos;){block_state}"
        ))
        .unwrap();
        assert_eq!(site.owner, "net/minecraft/world/level/Level");
        assert_eq!(site.name, "getBlockState");

        // Binary owner spelling normalizes to the internal form.
        let site = parse_invoke_selector(&format!(
            "net.minecraft.world.level.Level.getBlockState(Lnet/minecraft/core/BlockPos;){block_state}"
        ))
        .unwrap();
        assert_eq!(site.owner, "net/minecraft/world/level/Level");
        assert_eq!(site.name, "getBlockState");

        // `#` form with and without a descriptor.
        assert_eq!(
            parse_invoke_selector("Level#getBlockState"),
            Some(MethodRef {
                owner: "Level".into(),
                name: "getBlockState".into(),
                descriptor: String::new(),
            })
        );
        assert_eq!(
            parse_invoke_selector("Ldemo/Probe;mark(Ljava/lang/String;)V").unwrap(),
            MethodRef {
                owner: "demo/Probe".into(),
                name: "mark".into(),
                descriptor: "(Ljava/lang/String;)V".into(),
            }
        );
        assert_eq!(
            parse_invoke_selector("Ldemo/Probe;mark").unwrap(),
            MethodRef {
                owner: "demo/Probe".into(),
                name: "mark".into(),
                descriptor: String::new(),
            }
        );
        // Constructors stay representable; a hook simply never matches a stack
        // slot it cannot replace.
        assert_eq!(
            parse_invoke_selector("Ldemo/Probe;<init>()V").unwrap().name,
            "<init>"
        );
    }

    #[test]
    fn invoke_selectors_reject_everything_else() {
        for spec in [
            "",
            "   ",
            "Ldemo/Probe",
            "Ldemo/Probe;",
            "demo/Probe;mark()V",
            "Ldemo/Probe;mark(Ljava/lang/String;)V:2",
            "Ldemo/Probe;mark(x)V",
            "Ldemo/Probe;mark(Ljava/lang/String;)",
            "Ldemo/Probe;mar k()V",
            "Ldemo/Probe;mark()V extra",
            "demo/Probe",
            "Ldemo/Probe;mark([)V",
        ] {
            assert!(parse_invoke_selector(spec).is_none(), "accepted {spec:?}");
        }
    }

    #[test]
    fn invoke_plan_cancellation_pushes_the_default_return() {
        let jar = NativeJar::from_classes([invoke_target_class(), cancel_invoke_mixin()]);
        let site = MethodRef {
            owner: "demo/Probe".into(),
            name: "value".into(),
            descriptor: "()I".into(),
        };

        // The callback calls cancel() either way, but a non-cancellable plan
        // ignores the flag and the call runs.
        let plan = invoke_plan(site.clone(), false);
        let mut host = ValueHost { calls: 0 };
        let report = jar
            .execute_mixin_at_invoke(std::slice::from_ref(&plan), None, &[], &mut host)
            .unwrap();
        assert_eq!(report.target_result, Value::Int(42));
        assert_eq!(host.calls, 1, "the call reaches the host");
        assert!(!report.cancelled);
        assert_eq!(report.matched_invoke_sites, 1);
        assert_eq!(report.callback_results, vec![Value::Void]);

        // Cancellable: the call is suppressed and the descriptor's default
        // (0) takes its place, so the woven method answers 0.
        let plan = invoke_plan(site, true);
        let mut host = ValueHost { calls: 0 };
        let report = jar
            .execute_mixin_at_invoke(std::slice::from_ref(&plan), None, &[], &mut host)
            .unwrap();
        assert_eq!(report.target_result, Value::Int(0));
        assert_eq!(host.calls, 0, "the cancelled call never reaches the host");
        assert!(report.cancelled);
        assert_eq!(report.matched_invoke_sites, 1);
        assert_eq!(report.callback_results, vec![Value::Void]);
    }

    #[test]
    fn invoke_selector_without_a_descriptor_matches_every_overload() {
        let jar = NativeJar::from_classes([invoke_target_class(), cancel_invoke_mixin()]);
        let plan = invoke_plan(
            MethodRef {
                owner: "demo/Probe".into(),
                name: "value".into(),
                descriptor: String::new(),
            },
            true,
        );
        let mut host = ValueHost { calls: 0 };
        let report = jar
            .execute_mixin_at_invoke(std::slice::from_ref(&plan), None, &[], &mut host)
            .unwrap();
        assert_eq!(report.target_result, Value::Int(0));
        assert!(report.cancelled);
        assert_eq!(report.matched_invoke_sites, 1);
    }

    #[test]
    fn invoke_execution_requires_invoke_plans() {
        let jar = NativeJar::from_classes([invoke_target_class(), cancel_invoke_mixin()]);
        let mut plan = invoke_plan(
            MethodRef {
                owner: "demo/Probe".into(),
                name: "value".into(),
                descriptor: "()I".into(),
            },
            false,
        );
        plan.at = "HEAD".into();
        let error = jar
            .execute_mixin_at_invoke(
                std::slice::from_ref(&plan),
                None,
                &[],
                &mut ValueHost { calls: 0 },
            )
            .unwrap_err();
        assert!(
            error.to_string().contains("must name INVOKE"),
            "unexpected error: {error}"
        );
    }

    fn inject_invoke_annotation(method: &str, target: Option<&str>) -> Annotation {
        let mut at_values =
            BTreeMap::from([("value".into(), AnnotationValue::String("INVOKE".into()))]);
        if let Some(target) = target {
            at_values.insert("target".into(), AnnotationValue::String(target.into()));
        }
        Annotation {
            descriptor: "Lorg/spongepowered/asm/mixin/injection/Inject;".into(),
            values: BTreeMap::from([
                ("method".into(), string_array(&[method])),
                (
                    "at".into(),
                    AnnotationValue::Array(vec![AnnotationValue::Annotation(Box::new(
                        Annotation {
                            descriptor: "Lorg/spongepowered/asm/mixin/injection/At;".into(),
                            values: at_values,
                        },
                    ))]),
                ),
                ("cancellable".into(), AnnotationValue::Bool(false)),
            ]),
        }
    }

    fn invoke_mixin(class: &str, target: Option<&str>) -> ClassFile {
        ClassFile {
            name: class.into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![test_method(
                "onTick",
                "(Lorg/spongepowered/asm/mixin/injection/callback/CallbackInfo;)V",
                vec![0xb1],
                vec![inject_invoke_annotation("run()V", target)],
            )],
            annotations: vec![Annotation {
                descriptor: "Lorg/spongepowered/asm/mixin/Mixin;".into(),
                values: BTreeMap::from([("targets".into(), string_array(&["Ldemo/Target;"]))]),
            }],
            raw: Vec::new(),
        }
    }

    #[test]
    fn discovered_invoke_plans_parse_selectors_and_reject_mixed_anchors() {
        let jar = NativeJar::from_classes([
            target_class(),
            marker_mixin(
                "demo/HeadMixin",
                "run()V",
                "HEAD",
                false,
                "before",
                "before",
            ),
            invoke_mixin("demo/InvokeMixin", Some("Ldemo/Probe;target()V")),
        ]);
        let plans = jar.mixin_injection_plans();
        assert!(
            plans.iter().any(|plan| plan.at == "INVOKE"
                && plan.invoke_target
                    == Some(MethodRef {
                        owner: "demo/Probe".into(),
                        name: "target".into(),
                        descriptor: "()V".into(),
                    })),
            "unexpected plans: {plans:#?}"
        );
        assert!(jar.unresolved_invoke_plans().is_empty());

        let error = run_discovered(&jar, "run", &mut MarkerHost::default()).unwrap_err();
        assert!(
            matches!(&error, NativeError::Metadata(message)
                if message.contains("mixes INVOKE with HEAD/RETURN/TAIL")),
            "unexpected error: {error}"
        );

        // A selector this runtime cannot read stays report-only: discovery
        // keeps it out of the executable set and the diagnostic names it.
        let unresolved = NativeJar::from_classes([
            target_class(),
            invoke_mixin("demo/MissingTargetMixin", None),
            invoke_mixin("demo/OrdinalMixin", Some("Ldemo/Probe;target()V:3")),
        ]);
        assert!(
            unresolved.mixin_injection_plans().is_empty(),
            "unresolved selectors must not become executable plans"
        );
        let reported = unresolved.unresolved_invoke_plans();
        assert_eq!(reported.len(), 2, "unexpected report: {reported:#?}");
        assert!(reported.iter().all(|plan| plan.invoke_target.is_none()));
        assert!(reported.iter().all(|plan| plan.at == "INVOKE"));
    }

    #[test]
    fn default_for_normalizes_full_method_descriptors() {
        assert_eq!(Value::default_for("V"), Value::Void);
        assert_eq!(Value::default_for("I"), Value::Int(0));
        assert_eq!(Value::default_for("Ljava/lang/String;"), Value::Ref(None));
        assert_eq!(Value::default_for("()V"), Value::Void);
        assert_eq!(
            Value::default_for("(Lnet/minecraft/world/item/Item$Properties;)V"),
            Value::Void
        );
        assert_eq!(
            Value::default_for(
                "(Lnet/minecraft/core/Registry;Lnet/minecraft/resources/Identifier;Ljava/lang/Object;)I"
            ),
            Value::Int(0)
        );
        assert_eq!(
            Value::default_for("(I)Ljava/lang/String;"),
            Value::Ref(None)
        );
    }

    #[test]
    fn standard_host_resolves_registry_statics() {
        let mut host = StdHost::new();
        let item = MethodRef {
            owner: "net/minecraft/core/registries/Registries".into(),
            name: "ITEM".into(),
            descriptor: "Lnet/minecraft/core/Registry;".into(),
        };
        assert_eq!(
            Host::get_static(&mut host, &item).unwrap(),
            Value::Ref(Some("registry/minecraft:item".into()))
        );
        let block = MethodRef {
            owner: "net/minecraft/core/registries/BuiltInRegistries".into(),
            name: "BLOCK".into(),
            descriptor: "Lnet/minecraft/core/Registry;".into(),
        };
        assert_eq!(
            Host::get_static(&mut host, &block).unwrap(),
            Value::Ref(Some("registry/minecraft:block".into()))
        );
        let unknown = MethodRef {
            owner: "net/minecraft/core/registries/Registries".into(),
            name: "NOT_A_REGISTRY".into(),
            descriptor: "Lnet/minecraft/core/Registry;".into(),
        };
        assert_eq!(
            Host::get_static(&mut host, &unknown).unwrap(),
            Value::Ref(None)
        );
    }

    #[test]
    fn standard_host_records_plain_fabric_registry_register() {
        let register = MethodRef {
            owner: "net/minecraft/core/Registry".into(),
            name: "register".into(),
            descriptor: "(Lnet/minecraft/core/Registry;Lnet/minecraft/resources/Identifier;Ljava/lang/Object;)Ljava/lang/Object;".into(),
        };
        let mut host = StdHost::new();
        let registry = Host::get_static(
            &mut host,
            &MethodRef {
                owner: "net/minecraft/core/registries/Registries".into(),
                name: "ITEM".into(),
                descriptor: "Lnet/minecraft/core/Registry;".into(),
            },
        )
        .unwrap();
        let value = Value::Ref(Some("@indy:ruby-wand".into()));
        assert_eq!(
            Host::invoke(
                &mut host,
                &register,
                &[
                    registry,
                    Value::Ref(Some("identifier/ruby:wand".into())),
                    value.clone(),
                ],
            )
            .unwrap(),
            value
        );
        assert_eq!(host.registrations().len(), 1);
        let entry = &host.registrations()[0];
        assert_eq!(entry.registry, "minecraft:item");
        assert_eq!(entry.id, "ruby:wand");
        assert_eq!(entry.value, value);

        // A call without a registry marker stays invocation-only so the host
        // never invents a registry id.
        let mut host = StdHost::new();
        Host::invoke(
            &mut host,
            &register,
            &[
                Value::Ref(None),
                Value::Ref(Some("identifier/ruby:wand".into())),
                Value::Ref(Some("@indy:ruby-wand".into())),
            ],
        )
        .unwrap();
        assert!(host.registrations().is_empty());
    }

    #[test]
    fn void_host_call_does_not_store_a_phantom_reference() {
        fn u2(bytes: &mut Vec<u8>, value: u16) {
            bytes.extend_from_slice(&value.to_be_bytes());
        }
        fn utf8(bytes: &mut Vec<u8>, value: &str) {
            bytes.push(1);
            u2(bytes, value.len() as u16);
            bytes.extend_from_slice(value.as_bytes());
        }

        // `probe()` loads "ok", calls a host method that the StdHost does not
        // model and that returns void, stores the loaded value, and reads the
        // field back.  A void fallback that answered with a phantom `Ref(None)`
        // made `putstatic` store that phantom instead of "ok".
        let mut bytes = Vec::new();
        bytes.extend_from_slice(&0xCAFE_BABEu32.to_be_bytes());
        u2(&mut bytes, 0); // minor
        u2(&mut bytes, 52); // major
        u2(&mut bytes, 20); // constant-pool count
        utf8(&mut bytes, "demo/VoidStore"); // 1
        bytes.extend_from_slice(&[7, 0, 1]); // 2: Class
        utf8(&mut bytes, "java/lang/Object"); // 3
        bytes.extend_from_slice(&[7, 0, 3]); // 4: Class
        utf8(&mut bytes, "PROPS"); // 5
        utf8(&mut bytes, "Ljava/lang/String;"); // 6
        utf8(&mut bytes, "probe"); // 7
        utf8(&mut bytes, "()Ljava/lang/String;"); // 8
        utf8(&mut bytes, "ok"); // 9
        bytes.extend_from_slice(&[8, 0, 9]); // 10: String
        utf8(&mut bytes, "demo/Host"); // 11
        bytes.extend_from_slice(&[7, 0, 11]); // 12: Class
        utf8(&mut bytes, "consume"); // 13
        utf8(&mut bytes, "()V"); // 14
        bytes.extend_from_slice(&[12, 0, 13, 0, 14]); // 15: NameAndType
        bytes.extend_from_slice(&[10, 0, 12, 0, 15]); // 16: Methodref
        utf8(&mut bytes, "Code"); // 17
        bytes.extend_from_slice(&[12, 0, 5, 0, 6]); // 18: NameAndType
        bytes.extend_from_slice(&[9, 0, 2, 0, 18]); // 19: FieldRef

        u2(&mut bytes, 0x0021); // access
        u2(&mut bytes, 2); // this_class
        u2(&mut bytes, 4); // super_class
        u2(&mut bytes, 0); // interfaces
        u2(&mut bytes, 1); // fields
        u2(&mut bytes, 0x0009); // public static
        u2(&mut bytes, 5);
        u2(&mut bytes, 6);
        u2(&mut bytes, 0); // attributes
        u2(&mut bytes, 1); // methods
        u2(&mut bytes, 0x0009); // public static
        u2(&mut bytes, 7);
        u2(&mut bytes, 8);
        u2(&mut bytes, 1); // attributes
        u2(&mut bytes, 17); // Code
        bytes.extend_from_slice(&24u32.to_be_bytes()); // attribute length
        u2(&mut bytes, 2); // max_stack
        u2(&mut bytes, 0); // max_locals
        bytes.extend_from_slice(&12u32.to_be_bytes()); // code length
        bytes.extend_from_slice(&[
            0x12, 0x0a, // ldc #10 ("ok")
            0xb8, 0x00, 0x10, // invokestatic #16 (demo/Host.consume()V)
            0xb3, 0x00, 0x13, // putstatic #19 (PROPS)
            0xb2, 0x00, 0x13, // getstatic #19 (PROPS)
            0xb0, // areturn
        ]);
        u2(&mut bytes, 0); // exception_table_length
        u2(&mut bytes, 0); // code attributes
        u2(&mut bytes, 0); // class attributes

        let class = ClassFile::parse(&bytes).unwrap();
        assert!(
            class
                .method("probe", "()Ljava/lang/String;")
                .unwrap()
                .is_static()
        );
        let jar = NativeJar::from_classes([class]);
        let mut host = StdHost::new();
        assert_eq!(
            jar.invoke_method_with_args(
                "demo/VoidStore",
                "probe",
                "()Ljava/lang/String;",
                None,
                &[],
                &mut host,
            )
            .unwrap(),
            Value::Ref(Some("ok".into()))
        );
    }
    #[test]
    fn concrete_collection_classes_reach_the_mutable_table() {
        let mut host = StdHost::new();
        let map = Value::Ref(Some("java/util/TreeMap#0".into()));
        host.invoke_instance(
            &MethodRef {
                owner: "java/util/TreeMap".into(),
                name: "<init>".into(),
                descriptor: "()V".into(),
            },
            &map,
            &[],
        )
        .unwrap();
        host.invoke_instance(
            &MethodRef {
                owner: "java/util/TreeMap".into(),
                name: "put".into(),
                descriptor: "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;".into(),
            },
            &map,
            &[Value::Ref(Some("key".into())), Value::Int(7)],
        )
        .unwrap();
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/util/TreeMap".into(),
                    name: "getOrDefault".into(),
                    descriptor: "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;".into(),
                },
                &map,
                &[Value::Ref(Some("key".into())), Value::Int(-1)],
            )
            .unwrap(),
            Value::Int(7)
        );

        let list = Value::Ref(Some("java/util/concurrent/CopyOnWriteArrayList#1".into()));
        host.invoke_instance(
            &MethodRef {
                owner: "java/util/concurrent/CopyOnWriteArrayList".into(),
                name: "<init>".into(),
                descriptor: "()V".into(),
            },
            &list,
            &[],
        )
        .unwrap();
        host.invoke_instance(
            &MethodRef {
                owner: "java/util/List".into(),
                name: "add".into(),
                descriptor: "(Ljava/lang/Object;)Z".into(),
            },
            &list,
            &[Value::Ref(Some("element".into()))],
        )
        .unwrap();
        let iter = host
            .invoke_instance(
                &MethodRef {
                    owner: "java/util/List".into(),
                    name: "iterator".into(),
                    descriptor: "()Ljava/util/Iterator;".into(),
                },
                &list,
                &[],
            )
            .unwrap();
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/util/Iterator".into(),
                    name: "next".into(),
                    descriptor: "()Ljava/lang/Object;".into(),
                },
                &iter,
                &[],
            )
            .unwrap(),
            Value::Ref(Some("element".into()))
        );
    }

    #[test]
    fn integer_parse_failure_is_a_java_throwable() {
        let mut host = StdHost::new();
        let error = host
            .invoke(
                &MethodRef {
                    owner: "java/lang/Integer".into(),
                    name: "parseInt".into(),
                    descriptor: "(Ljava/lang/String;)I".into(),
                },
                &[Value::Ref(None)],
            )
            .unwrap_err();
        assert!(
            matches!(
                &error,
                NativeError::UncaughtException { class, .. }
                    if class == "java/lang/NumberFormatException"
            ),
            "{error:?}"
        );
    }

